ref = [1,2,3,4,1,2,5,1,2,3,4,5]
frames = 3

def fifo(ref):
    q = []
    faults = 0
    for p in ref:
        if p not in q:
            faults += 1
            if len(q) < frames:
                q.append(p)
            else:
                q.pop(0)
                q.append(p)
    return faults

def lru(ref):
    stack = []
    faults = 0
    for p in ref:
        if p in stack:
            stack.remove(p)
            stack.append(p)
        else:
            faults += 1
            if len(stack) < frames:
                stack.append(p)
            else:
                stack.pop(0)
                stack.append(p)
    return faults

def optimal(ref):
    frames_set = []
    faults = 0
    for i, p in enumerate(ref):
        if p in frames_set:
            continue
        faults += 1
        if len(frames_set) < frames:
            frames_set.append(p)
        else:
            future = {f: (ref[i+1:].index(f) if f in ref[i+1:] else float('inf')) for f in frames_set}
            victim = max(future, key=future.get)
            frames_set[frames_set.index(victim)] = p
    return faults

print(fifo(ref))
print(lru(ref))
print(optimal(ref))

